import cmath
import math
from numbers import Real


def frequency_profile(samples):
    if not isinstance(samples, (list, tuple)):
        raise TypeError("samples must be a list or tuple")
    if not samples:
        raise ValueError("samples cannot be empty")

    values = []
    for sample in samples:
        if isinstance(sample, bool) or not isinstance(sample, Real):
            raise TypeError("samples must be real numbers")
        value = float(sample)
        if not math.isfinite(value):
            raise ValueError("samples must be finite")
        values.append(value)

    size = len(values)
    magnitudes = []
    for frequency in range((size + 1) // 2):
        total = sum(
            value * cmath.exp(-2j * math.pi * frequency * index / size)
            for index, value in enumerate(values)
        )
        magnitudes.append(abs(total) / size)
    return tuple(magnitudes)

